{
    Node *n = my_alloc(sizeof *n);
    if (n == NULL) return head;
    n->value = value;
    n->next = NULL;
    if (head == NULL) return n;
    Node *last = head;
    while (last->next != NULL) last = last->next;
    last->next = n;
    return head;
