Node *list_remove(Node *head, int value)
{
    if (head == NULL) return NULL;
    if (head->value == value) {            /* the head itself goes */
        Node *next = head->next;
        my_free(head);
        return next;
    }
    for (Node *prev = head; prev->next != NULL; prev = prev->next) {
        if (prev->next->value == value) {
            Node *gone = prev->next;
            prev->next = gone->next;        /* skip over it */
            my_free(gone);
            break;
        }
    }
    return head;
}
